// src/services/websocket.js
import mockBackend from './MockBackend';

class WebSocketService {
  constructor() {
    this.roomId = null;
    this.userId = null;
    this.callbacks = {};
    this.unsubscribe = null;
  }

  connect(roomId, userId, username, callbacks) {
    this.roomId = roomId;
    this.userId = userId;
    this.callbacks = callbacks;

    console.log(`Connecting to room: ${roomId} as ${username}`);

    // Check if room exists
    let room = mockBackend.getRoom(roomId);
    
    if (!room) {
      // Create new room (Host)
      console.log('Creating new room as HOST');
      room = mockBackend.createRoom(roomId, userId, username);
      
      // Set role
      if (callbacks.onRoleAssigned) {
        callbacks.onRoleAssigned({ userId, role: 'HOST' });
      }
      
      // Send initial video state
      if (callbacks.onVideoChange) {
        callbacks.onVideoChange({ videoId: room.state.videoId });
      }
    } else {
      // Join existing room (Participant)
      console.log('Joining existing room as PARTICIPANT');
      const result = mockBackend.joinRoom(roomId, userId, username);
      
      if (result && callbacks.onRoleAssigned) {
        callbacks.onRoleAssigned({ userId, role: result.role });
        
        // Send initial video state
        if (callbacks.onVideoChange) {
          callbacks.onVideoChange({ videoId: result.state.videoId });
        }
        
        // Send current playback state
        if (result.state.isPlaying && callbacks.onPlay) {
          callbacks.onPlay({ currentTime: result.state.currentTime });
        }
      }
    }
    
    // Subscribe to room events
    this.unsubscribe = mockBackend.subscribe(roomId, (type, payload) => {
      console.log(`Received: ${type}`, payload);
      
      switch(type) {
        case 'play':
          this.callbacks.onPlay && this.callbacks.onPlay(payload);
          break;
        case 'pause':
          this.callbacks.onPause && this.callbacks.onPause(payload);
          break;
        case 'seek':
          this.callbacks.onSeek && this.callbacks.onSeek(payload);
          break;
        case 'change_video':
          this.callbacks.onVideoChange && this.callbacks.onVideoChange(payload);
          break;
        case 'user_joined':
          this.callbacks.onUserJoined && this.callbacks.onUserJoined(payload);
          break;
        case 'user_left':
          this.callbacks.onUserLeft && this.callbacks.onUserLeft(payload);
          break;
        case 'role_assigned':
          this.callbacks.onRoleAssigned && this.callbacks.onRoleAssigned(payload);
          break;
        case 'participant_removed':
          this.callbacks.onParticipantRemoved && this.callbacks.onParticipantRemoved(payload);
          break;
        case 'chat':
          this.callbacks.onChat && this.callbacks.onChat(payload);
          break;
        case 'refresh':
          this.refreshParticipants();
          break;
        default:
          break;
      }
    });
    
    // Get existing participants after delay
    setTimeout(() => {
      this.refreshParticipants();
    }, 500);
  }

  refreshParticipants() {
    const participants = mockBackend.getParticipants(this.roomId);
    participants.forEach(p => {
      if (p.userId !== this.userId && this.callbacks.onUserJoined) {
        this.callbacks.onUserJoined(p);
      }
    });
  }

  sendPlay(roomId, userId) {
    console.log(`Sending PLAY`);
    mockBackend.sendPlay(roomId, userId);
  }

  sendPause(roomId, userId) {
    console.log(`Sending PAUSE`);
    mockBackend.sendPause(roomId, userId);
  }

  sendSeek(roomId, userId, time) {
    console.log(`Sending SEEK to ${time}`);
    mockBackend.sendSeek(roomId, userId, time);
  }

  sendChangeVideo(roomId, userId, videoId) {
    console.log(`Sending CHANGE_VIDEO to ${videoId}`);
    mockBackend.sendChangeVideo(roomId, userId, videoId);
  }

  sendAssignRole(roomId, userId, targetId, role) {
    console.log(`Sending ASSIGN_ROLE: ${targetId} -> ${role}`);
    mockBackend.sendAssignRole(roomId, userId, targetId, role);
  }

  sendRemoveParticipant(roomId, userId, targetId) {
    console.log(`Sending REMOVE_PARTICIPANT: ${targetId}`);
    mockBackend.sendRemoveParticipant(roomId, userId, targetId);
  }

  sendChat(roomId, userId, username, message) {
    console.log(`Sending CHAT: ${message}`);
    mockBackend.sendChat(roomId, userId, username, message);
  }

  disconnect() {
    if (this.unsubscribe) {
      this.unsubscribe();
    }
    if (this.roomId && this.userId) {
      mockBackend.sendLeave(this.roomId, this.userId);
    }
  }
}

export default WebSocketService;
